 "más básico →": "basischer →",
 "<b>pH 1,5</b><br>Jugo gástrico": "<b>pH 1,5</b><br>Magensaft",
 "<b>pH 2,2</b><br>Limón": "<b>pH 2,2</b><br>Zitrone",
